def reject_injected_java_options() -> None:
    present = [name for name in INJECTED_JAVA_ENVIRONMENT if name in os.environ]
    assert not present, 'Unexpected injected Java options: ' + ', '.join(present)


def write_new(path: Path, value: object) -> None:
    with path.open('x') as output:
        json.dump(value, output, indent=2, sort_keys=True)
        output.write('\n')


def source_hashes() -> dict:
    files = sorted((HERE / 'src').rglob('*.java')) + sorted((HERE / 'preimage').rglob('*.java'))
    files += [HERE / 'build_overlay_source.py', HERE / 'run_page_diagnostic.py', HERE / 'diagnostic-overlay.patch',
              HERE / 'protocol.md']
    return {p.relative_to(HERE).as_posix(): identity.sha(p) for p in files}


def unchanged_source_regions() -> dict:
    original = (HERE / 'preimage' / REL).read_text()
    modified = (HERE / 'src' / REL).read_text()
    regions = {}
    for name, start, end in [('projectionPlan', None, '/**\n * Evaluation-local last-value memo.'),
                             ('factorMemoAndFactorPage', '\tprivate static final class FactorMemo', '\tprivate boolean allocate(')]:
        def region(text):
            begin = text.index(start) if start is not None else 0
            return text[begin:text.index(end, begin)]
        assert region(original) == region(modified), name
        regions[name] = {'unchanged': True, 'sha256': shared.sha_text(region(original))}
    return regions


def prepare() -> None:
    reject_injected_java_options()
    parent_plan = shared.read_plan()
    parent_runtime = shared.read_runtime(parent_plan)
    original_sources = json.loads(identity.ORIGINAL_SOURCES.read_text())
    assert identity.sha(HERE / 'preimage' / REL) == original_sources[PRODUCTION_REL]
    assert identity.sha(HERE / 'preimage' / REL) == identity.sha(
        ROOT / 'result-coordinate-evidence/materializer-followup/baseline/preimages' / PRODUCTION_REL)
    sources = source_hashes()
    with (SHARED / 'pilot/dense/samples.jsonl').open() as stream:
        reference_metadata = json.loads(stream.readline())
    assert reference_metadata['source'] == identity.ORIGINAL_SOURCE
    java_identity = {key: reference_metadata[key] for key in ('javaVersion', 'javaVendor', 'maxHeapBytes')}
    plan = {'format': 1, 'purpose': 'Page occupancy, key multiplicity and accounting diagnostic only',
            'frozenOriginalSource': identity.ORIGINAL_SOURCE, 'sourceHashes': sources,
            'unchangedSourceRegions': unchanged_source_regions(),
            'instrumentedIdentity': identity.ORIGINAL_SOURCE + '+page-diagnostic-sha256-' + identity.canonical_sha(sources),
            'baseHarnessRuntime': parent_runtime, 'baseHarnessProtocolSha256': identity.sha(shared.PLAN),
            'baseHarnessRuntimeSha256': identity.sha(shared.RUNTIME), 'fixture': parent_plan['fixture'],
            'java': str(shared.JAVA), 'jvmArguments': parent_plan['jvmArguments'],
            'expectedJavaIdentity': java_identity,
            'expectedJvmArguments': parent_plan['jvmArguments'] + [
                f'-Drdf4j.lmdb.factorPageDiagnostic.output={HERE / "page-records"}',
                '-Drdf4j.lmdb.resultCoordinateTransport=dense'],
            'rejectedInjectedEnvironment': list(INJECTED_JAVA_ENVIRONMENT),
            'arm': 'dense', 'warmup': 3, 'iterations': 1, 'consumption': 'full',
            'strategy': parent_plan['strategy'],
            'noLatencyOrAllocationComparison': True, 'allOriginalSourcesAndArtifactsPreserved': True,
            'occupancy': {'stored': 'Nonnull WeakReference slots at removal, not distinct ever-touched cells.',
                          'live': 'WeakReference.get() nonnull at removal. Transient; observation can briefly strengthen a referent.',
                          'keyTable': 'Only pages still present before final materializer close. Pre-close removal counts explicitly limit coverage.'},
            'inferredUncappedGeometry': {'pagesByTarget': {'s': 0, 'a': 0, 'l0': 128, 'l1': 8192, 'r0': 128, 'r1': 8192},
                                       'pages': 16640, 'chargedPageBytes': 272629760,
                                       'singletonPages': 16384, 'full64CellPages': 256,
                                       'status': 'Prospective source-based hypothesis, not measured occupancy.'},
            'successCriteria': 'Four exact result bags/checksums; zero endpoint ledgers; measured normal compiled IR and native root; all page/directory/memo counts and charge sums reconcile; all diagnostic table coverage stated.',
            'failurePolicy': 'Preserve all failures and all records. No substitute forks or performance-driven shape changes.'}
    write_new(PLAN, plan)
    print(json.dumps({'protocol': str(PLAN), 'javaExecuted': False, 'instrumentedIdentity': plan['instrumentedIdentity']}, indent=2))


def read_plan() -> tuple[dict, dict]:
    reject_injected_java_options()
    plan = json.loads(PLAN.read_text())
    assert plan['sourceHashes'] == source_hashes(), 'Diagnostic source changed after prospective pin'
    assert plan['unchangedSourceRegions'] == unchanged_source_regions()
    parent_plan = shared.read_plan()
    assert identity.sha(shared.PLAN) == plan['baseHarnessProtocolSha256']
    assert identity.sha(shared.RUNTIME) == plan['baseHarnessRuntimeSha256']
    assert shared.read_runtime(parent_plan) == plan['baseHarnessRuntime']
    return plan, parent_plan


def compile_overlay() -> None:
    plan, _ = read_plan()
    raw_classes = HERE / 'compiled-output'
    raw_classes.mkdir(exist_ok=False)
    classes = HERE / 'classes'
    classes.mkdir(exist_ok=False)
    base = plan['baseHarnessRuntime']
    command = [str(shared.JAVA.with_name('javac')), '--release', '25', '-cp', base['classpath'], '-d', str(raw_classes)]
    command += [str(p) for p in sorted((HERE / 'src').rglob('*.java'))]
    write_new(HERE / 'compile-command.json', {'argv': command, 'cwd': str(ROOT)})
    with (HERE / 'compile.log').open('x') as output:
        completed = subprocess.run(command, cwd=ROOT, stdout=output, stderr=subprocess.STDOUT)
    assert completed.returncode == 0, 'Diagnostic compile failed; preserve all outputs'
    emitted = identity.tree_files(raw_classes)
    changed_class = 'org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer.class'
    helper_class = 'org/eclipse/rdf4j/sail/lmdb/evaluation/FactorPageDiagnostics.class'
    unchanged_classes = {'org/eclipse/rdf4j/sail/lmdb/evaluation/' + name for name in (
        'NativeResultMaterializerPlan.class', 'NativeResultMaterializer$FactorMemo.class',
        'NativeResultMaterializer$FactorPage.class')}
    assert set(emitted) == {changed_class, helper_class} | unchanged_classes, 'Unexpected emitted class surface'
    original_tree = Path(base['manifest'][2]['path'])
    comparisons = {}
    for name, descriptor in emitted.items():
        original = original_tree / name
        if name == helper_class:
            assert not original.exists()
            comparisons[name] = {'runtimeSelection': 'additive overlay', 'meaning': 'new diagnostic helper',
                                 'compiledSha256': descriptor['sha256']}
        elif name == changed_class:
            assert original.is_file() and identity.sha(original) != descriptor['sha256']
            comparisons[name] = {'runtimeSelection': 'additive overlay', 'meaning': 'sole changed original production class',
                                 'compiledSha256': descriptor['sha256'], 'originalSha256': identity.sha(original)}
        else:
            assert original.is_file() and name in unchanged_classes, name
            comparisons[name] = {'runtimeSelection': 'untouched original frozen entry',
                                 'meaning': 'Source body unchanged; generated debug line tables may differ. Raw output preserved but excluded from overlay.',
                                 'compiledSha256': descriptor['sha256'], 'originalSha256': identity.sha(original)}
    for name in (changed_class, helper_class):
        destination = classes / name
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(raw_classes / name, destination)
    classpath = str(classes) + os.pathsep + base['classpath']
    manifest = identity.classpath_manifest(classpath)
    assert manifest[1:] == base['manifest']
    write_new(RUNTIME, {'classpath': classpath, 'manifest': manifest, 'rawCompiledFiles': emitted,
                        'overlayFiles': identity.tree_files(classes),
                        'shadowComparison': comparisons, 'protocolSha256': identity.sha(PLAN),
                        'sourceHashes': plan['sourceHashes'], 'unchangedOriginalRuntimeEntries': 127,
                        'unchangedHarnessEntries': 1})
    print(json.dumps({'compiled': True, 'originalAndHarnessEntriesUnchanged': 128, 'classShadowing': comparisons}, indent=2))


def read_runtime(plan: dict) -> dict:
    runtime = json.loads(RUNTIME.read_text())
    assert runtime['sourceHashes'] == plan['sourceHashes'] and runtime['protocolSha256'] == identity.sha(PLAN)
    assert identity.classpath_manifest(runtime['classpath']) == runtime['manifest']
    assert runtime['manifest'][1:] == plan['baseHarnessRuntime']['manifest']
    return runtime


def histogram(values) -> dict[str, int]:
    return {str(key): count for key, count in sorted(Counter(values).items())}


def analyze_owner(path: Path) -> dict:
    records = [json.loads(line) for line in path.read_text().splitlines()]
    summary = records[-1]
    pages = records[:-1]
    assert summary['type'] == 'factor-page-summary'
    assert all(page['type'] == 'factor-page' and page['owner'] == summary['owner'] for page in pages)
    checks = {}

    def check(name: str, condition: bool) -> None:
        checks[name] = bool(condition)

    n = summary['pageAdmissions']
    preclose = summary['pagesRetiredByNamespace'] + summary['pagesClearedBeforeFinalClose']
    check('pageAdmissionsEqualReleases', n == summary['pageReleases'])
    check('pageReservationsEqualAdmissionsAndConstructorFailures', summary['pagePayloadReservationGrants'] == n + summary['pageConstructionFailureReleases'])
    check('pageAttemptsReconcile', summary['pageAdmissionAttempts'] == n + summary['pageConstructionFailureReleases'] +
          summary['pagePayloadRefusals'] + summary['directoryInitialRefusals'] + summary['directoryGrowthRefusals'] +
          summary['directoryCapacityOverflowRefusals'])
    check('observedPageReleaseBytesWithinGrantedBytes', 0 <= summary['pagePayloadBytesObservedBeforeRelease'] <= summary['pagePayloadBytesGranted'])
    check('declaredPageReleasesReconcile', summary['pageDeclaredBytesReleased'] == n * summary['pageChargeBytes'])
    check('pageTableCountReconciles', len(pages) == summary['snapshotPages'] == summary['snapshotExpectedPages'] == n - preclose)
    check('pageTableChargeReconciles', sum(page['reservationBytesAtSnapshot'] for page in pages) == summary['snapshotPageClaimBytes'])
    check('pageTableKeysUnique', len({tuple(page[k] for k in ('target', 'namespace', 'group', 'parent', 'column', 'pageIndex')) for page in pages}) == len(pages))
    check('pageCountsByTargetReconcile', sum(summary['admissionsByTarget']) == n)
    check('factorHitsByTargetReconcile', sum(summary['factorHitsByTarget']) == summary['factorHits'])
    check('blockedPublicationsByTargetReconcile', sum(summary['blockedMissingPagesByTarget']) == summary['blockedMissingPagePublications'])
    check('directoryReserveAttemptsReconcile', summary['directoryReserveAttempts'] == summary['directoryReservationGrants'] + summary['directoryInitialRefusals'] + summary['directoryGrowthRefusals'])
    check('observedDirectoryReleaseBytesWithinGrantedBytes', 0 <= summary['directoryBytesObservedBeforeRelease'] <= summary['directoryBytesGranted'])
    check('directoryGrantLessObservedReleaseDeltaReconciles', summary['directoryGrantedLessObservedReleaseBytes'] == summary['directoryBytesGranted'] - summary['directoryBytesObservedBeforeRelease'])
    check('memoReserveAttemptsReconcile', summary['memoReserveAttempts'] == summary['memoReservationGrants'] + summary['memoRefusals'])
    check('observedMemoReleaseBytesWithinGrantedBytes', 0 <= summary['memoBytesObservedBeforeRelease'] <= summary['memoBytesGranted'])
    check('finalCoverageFlagCorrect', summary['finalPageTableCoversAllAdmissions'] == (preclose == 0 and len(pages) == n))
    for suffix, page_field in [('OccupiedSlots', 'occupiedWeakReferenceSlots'), ('LiveReferents', 'liveWeakReferentsAtSnapshot')]:
        final_hist = [0] * 65
        for page in pages:
            final_hist[page[page_field]] += 1
        check('final' + suffix + 'HistogramMatchesTable', final_hist == summary['final' + suffix])
        check('beforeFinal' + suffix + 'HistogramReconciles', sum(summary['beforeFinal' + suffix]) == preclose)
        check('allRemoved' + suffix + 'HistogramReconciles', sum(summary['allRemoved' + suffix]) == n and
              summary['allRemoved' + suffix] == [a+b for a, b in zip(summary['final' + suffix], summary['beforeFinal' + suffix])])
    check('liveReferentsNeverExceedStoredSlots', all(0 <= p['liveWeakReferentsAtSnapshot'] <= p['occupiedWeakReferenceSlots'] <= 64 for p in pages))
    targets = []
    for target, name in enumerate(summary['targetNames']):
        selected = [page for page in pages if page['target'] == target]
        parent_identities = Counter((p['namespace'], p['group'], p['parent'], p['column']) for p in selected)
        occupied = sum(p['occupiedWeakReferenceSlots'] for p in selected)
        charge = sum(p['reservationBytesAtSnapshot'] for p in selected)
        declared = len(selected) * summary['pageChargeBytes']
        targets.append({'target': target, 'name': name, 'pagesInFinalTable': len(selected),
                        'admissions': summary['admissionsByTarget'][target], 'chargedPageBytesAtSnapshot': charge,
                        'declaredStructuralPageBytes': declared,
                        'occupiedWeakReferenceSlots': occupied, 'slotCapacity': len(selected) * 64,
                        'chargedBytesPerOccupiedSlot': charge / occupied if occupied else None,
                        'declaredStructuralBytesPerOccupiedSlot': declared / occupied if occupied else None,
                        'occupiedSlotHistogram': histogram(p['occupiedWeakReferenceSlots'] for p in selected),
                        'liveReferentHistogram': histogram(p['liveWeakReferentsAtSnapshot'] for p in selected),
                        'namespacePageCounts': histogram(p['namespace'] for p in selected),
                        'groupPageCounts': histogram(p['group'] for p in selected),
                        'pageIndexCounts': histogram(p['pageIndex'] for p in selected),
                        'distinctParentIdentities': len(parent_identities),
                        'pagesPerParentIdentityHistogram': histogram(parent_identities.values()),
                        'factorHits': summary['factorHitsByTarget'][target],
                        'blockedMissingPagePublicationCalls': summary['blockedMissingPagesByTarget'][target]})
    occupied = sum(p['occupiedWeakReferenceSlots'] for p in pages)
    parents = Counter((p['namespace'], p['group'], p['parent']) for p in pages)
    return {'raw': str(path), 'summary': summary, 'checks': checks, 'allChecksPassed': all(checks.values()),
            'grantedBytesNotObservedAtExplicitRelease': {
                'pages': summary['pagePayloadBytesGranted'] - summary['pagePayloadBytesObservedBeforeRelease'],
                'directory': summary['directoryBytesGranted'] - summary['directoryBytesObservedBeforeRelease'],
                'memo': summary['memoBytesGranted'] - summary['memoBytesObservedBeforeRelease']},
            'tableCoverage': 'all admitted pages' if summary['finalPageTableCoversAllAdmissions'] else 'final retained pages only; earlier removed keys absent',
            'tableNamespacePageCounts': histogram(p['namespace'] for p in pages),
            'tableDistinctNamespaceGroupParentIdentities': len(parents),
            'tablePagesPerNamespaceGroupParentHistogram': histogram(parents.values()),
            'tableSlotOccupancyFraction': occupied / (len(pages) * 64) if pages else None,
            'targets': targets}


def analyze() -> None:
    plan, _ = read_plan()
    observations = json.loads((HERE / 'run/validation.json').read_text())
    records = [json.loads(line) for line in (HERE / 'run/samples.jsonl').read_text().splitlines()]
    metadata = records[0]
    samples = records[1:]
    metadata_checks = {'instrumentedSourceIdentity': metadata['source'] == plan['instrumentedIdentity'],
                       'exactJvmArguments': metadata['jvmArguments'] == plan['expectedJvmArguments'],
                       'javaVersionVendorHeap': all(metadata[key] == value for key, value in plan['expectedJavaIdentity'].items()),
                       'originalLedgerLimits': metadata['globalLedgerLimitBytes'] == 1073741824 and metadata['perQueryLedgerLimitBytes'] == 268435456,
                       'configuredNativeAndPreferredAdjacency': metadata['nativeEvaluation'] and metadata['directAdjacency'] and metadata['directAdjacencyMode'] == 'PREFER'}
    paths = sorted((HERE / 'page-records').glob('owner-*.jsonl'), key=lambda p: int(p.stem.split('-')[1]))
    owners = [analyze_owner(path) for path in paths]
    assert len(owners) == len(samples) == 4, 'Do not infer query/owner correspondence if it is not one owner per serial query'
    for index, (owner, sample) in enumerate(zip(owners, samples), 1):
        assert owner['summary']['owner'] == index
        owner['query'] = {'stage': sample['stage'], 'iteration': sample['iteration'],
                          'rows': sample['rows'], 'checksum': sample['checksum'], 'exactBagValid': sample['exactBagValid'],
                          'ledgerPeakBytes': sample['ledgerPeakBytes'], 'ledgerAfterBytes': sample['ledgerAfterBytes'],
                          'successfulSelections': sample['successfulSelections'], 'counters': sample['counters']}
    valid = all(metadata_checks.values()) and observations['allResultsExact'] and observations['nativeOuterRoot'] and observations['compiledIr'] and all(o['allChecksPassed'] for o in owners)
    result = {'format': 1, 'validDiagnostic': valid, 'protocolSha256': identity.sha(PLAN),
              'metadataIdentityChecks': metadata_checks,
              'observedSource': metadata['source'], 'observedJvmArguments': metadata['jvmArguments'],
              'observedJavaIdentity': {key: metadata[key] for key in plan['expectedJavaIdentity']},
              'scope': 'One instrumented DENSE JVM, 3 warmups + 1 measurement; no latency/allocation inference.',
              'instrumentationCaveat': 'WeakReference.get() can briefly strengthen referents. Extra counters, close-time table, JSON allocations and IO alter performance/GC; only structural diagnostics are interpreted.',
              'chargeReconciliation': 'Reservation.bytes() is the remaining claim at the observation. An earlier QueryLedger.close() can release it before the materializer does. Grant-minus-observed-release deltas are separate from declared page capacity, exact page close counts, and the endpoint ledger; a nonzero delta alone does not establish a leak.',
              'parentIdentityDefinition': 'A parent token is scoped by namespace and adjacency group. Per-target grouping also includes tuple column.',
              'firstRefusedKeyFields': ['target', 'namespace', 'group', 'parent', 'column', 'pageIndex'],
              'firstRefusalKinds': {'0': 'none', '1': 'initial directory', '2': 'directory growth or capacity overflow', '3': 'page payload'},
              'prospectiveUncappedGeometry': plan['inferredUncappedGeometry'], 'owners': owners}
    write_new(HERE / 'analysis.json', result)
    assert valid, 'Diagnostic failed validation; preserve records and report the failed checks'
    measured = owners[-1]
    print(json.dumps({'validDiagnostic': valid, 'measuredSummary': measured['summary'], 'measuredTargets': measured['targets']}, indent=2))


def run() -> None:
    plan, parent_plan = read_plan()
    runtime = read_runtime(plan)
    records = HERE / 'page-records'
    records.mkdir(exist_ok=False)
    instrumented_plan = dict(parent_plan)
    instrumented_plan['jvmArguments'] = plan['jvmArguments'] + [f'-Drdf4j.lmdb.factorPageDiagnostic.output={records}']
    instrumented_plan['frozenProductionSource'] = plan['instrumentedIdentity']
    write_new(HERE / 'run-context.json', {'protocolSha256': identity.sha(PLAN), 'runtimeSha256': identity.sha(RUNTIME),
                                      'diagnosticOutput': str(records), 'fixtureAndHarnessUnchanged': True,
                                      'meaning': 'All latency and allocated-byte fields are contaminated by instrumentation and must not be compared.'})
    shared.run_arm(HERE / 'run', instrumented_plan, runtime, 'dense', plan['warmup'], plan['iterations'])
    read_runtime(plan)
    analyze()


